362	        float* first_trailing = output_data +
363	            static_cast<int64_t>(stop) * n + stop;
364	        check_cublas(
365	            cublasGemmStridedBatchedEx(
366	                blas, CUBLAS_OP_N, CUBLAS_OP_T,
367	                trailing, trailing, width,
368	                &minus_one,
369	                first_panel, CUDA_R_32F, n, matrix_stride,
370	                first_panel, CUDA_R_32F, n, matrix_stride,
371	                &one,
372	                first_trailing, CUDA_R_32F, n, matrix_stride,
