655	__global__ void batch_lower_copy_kernel(
656	    const float* __restrict__ input,
657	    float* __restrict__ output,
658	    int n,
659	    int batch
660	) {
661	    const int total_rows = batch * n;
662	    const int warp = static_cast<int>(threadIdx.x) >> 5;
663	    const int lane = static_cast<int>(threadIdx.x) & 31;
664	    for (int linear_row = static_cast<int>(blockIdx.x) * 8 + warp;
665	         linear_row < total_rows;
666	         linear_row += static_cast<int>(gridDim.x) * 8) {
667	        const int row = linear_row % n;
668	        const long long base = static_cast<long long>(linear_row) * n;
669	        const int full_vectors = (row + 1) / 4;
670	        const float4* input_vectors = reinterpret_cast<const float4*>(
671	            input + base
672	        );
673	        float4* output_vectors = reinterpret_cast<float4*>(output + base);
674	        for (int vector = lane; vector < full_vectors;
675	             vector += 32) {
676	            output_vectors[vector] = input_vectors[vector];
677	        }
678	        const int tail = full_vectors * 4;
679	        for (int col = tail + lane; col <= row; col += 32) {
680	            output[base + col] = input[base + col];
681	        }
682	    }
683	}
