686	    TORCH_CHECK(input.is_cuda() && output.is_cuda(), "CUDA tensors required");
687	    TORCH_CHECK(
688	        input.scalar_type() == torch::kFloat32
689	        && output.scalar_type() == torch::kFloat32,
690	        "FP32 tensors required"
691	    );
692	    TORCH_CHECK(
693	        input.dim() == 3 && input.size(1) == input.size(2)
694	        && input.is_contiguous() && output.is_contiguous()
695	        && input.sizes() == output.sizes(),
696	        "matching contiguous batched square matrices required"
697	    );
698	    const int n = static_cast<int>(input.size(1));
699	    const int batch = static_cast<int>(input.size(0));
700	    TORCH_CHECK((n & 3) == 0, "matrix width must be float4 aligned");
701	    const int rows = batch * n;
702	    const int row_groups = (rows + 7) / 8;
703	    const int blocks = row_groups < 2048 ? row_groups : 2048;
704	    batch_lower_copy_kernel<<<
705	        blocks, 256, 0,
706	        c10::cuda::AC_CAT(getCurrentCUDA, AC_CAT(Str, eam))()
707	    >>>(
708	        input.data_ptr<float>(), output.data_ptr<float>(), n, batch
709	    );
