714	    float* __restrict__ output,
715	    int n,
716	    int batch
717	) {
718	    const int total_rows = batch * n;
719	    const int warp = static_cast<int>(threadIdx.x) >> 5;
720	    const int lane = static_cast<int>(threadIdx.x) & 31;
721	    for (int linear_row = static_cast<int>(blockIdx.x) * 8 + warp;
722	         linear_row < total_rows;
