724	        const int row = linear_row % n;
725	        const long long base = static_cast<long long>(linear_row) * n;
726	        const int first = row + 1;
727	        const int aligned = (first + 3) & ~3;
728	        for (int col = first + lane;
729	             col < aligned && col < n;
730	             col += 32) {
