767	    float* __restrict__ output,
768	    int* __restrict__ flags,
769	    int flag_count,
770	    int n,
771	    int batch
772	) {
773	    for (int index = static_cast<int>(blockIdx.x) * blockDim.x
774	             + static_cast<int>(threadIdx.x);
775	         index < flag_count;
776	         index += static_cast<int>(gridDim.x) * blockDim.x) {
777	        flags[index] = 0;
