782	    for (int linear_row = static_cast<int>(blockIdx.x) * 16 + warp;
783	         linear_row < total_rows;
784	         linear_row += static_cast<int>(gridDim.x) * 16) {
785	        const int row = linear_row % n;
786	        const long long base = static_cast<long long>(linear_row) * n;
787	        const int aligned_col = (row + 3) & ~3;
788	        const int scalar_stop = aligned_col < n ? aligned_col : n;
789	        for (int col = row + lane; col < scalar_stop; col += 32) {
790	            output[base + col] = input[base + col];
791	        }
792	        const int first_vector = aligned_col / 4;
793	        const int vector_count = n / 4;
