796	        );
797	        float4* output_vectors = reinterpret_cast<float4*>(output + base);
798	        for (int vector = first_vector + lane;
799	             vector < vector_count; vector += 64) {
800	            output_vectors[vector] = input_vectors[vector];
801	            const int second = vector + 32;
802	            if (second < vector_count) {
803	                output_vectors[second] = input_vectors[second];
804	            }
805	        }
806	    }
807	}
