853	    long long converted_stride_1
854	) {
855	    __shared__ float tile[32][33];
856	    const int batch = static_cast<int>(blockIdx.z);
857	    const int source_col = static_cast<int>(blockIdx.x) * 32 + threadIdx.x;
858	    const int source_row = static_cast<int>(blockIdx.y) * 32 + threadIdx.y;
859	    for (int offset = 0; offset < 32; offset += 8) {
860	        if (source_row + offset < panel_rows
861	                && source_col < trailing_rows) {
862	            tile[threadIdx.y + offset][threadIdx.x] = panel[
863	                static_cast<long long>(batch) * panel_stride_0
864	                + static_cast<long long>(source_row + offset) * panel_stride_1
865	                + source_col
866	            ];
867	        }
868	    }
