871	    const int output_col = static_cast<int>(blockIdx.y) * 32 + threadIdx.x;
872	    const int output_row = static_cast<int>(blockIdx.x) * 32 + threadIdx.y;
873	    for (int offset = 0; offset < 32; offset += 8) {
874	        if (output_row + offset < trailing_rows
875	                && output_col < panel_rows) {
876	            converted[
877	                static_cast<long long>(batch) * converted_stride_0
878	                + static_cast<long long>(output_row + offset)
879	                    * converted_stride_1
880	                + output_col
881	            ] = __float2half_rn(tile[threadIdx.x][threadIdx.y + offset]);
882	        }
883	    }
884	}
